  "narrative": {
    "northStar": "The Friendly Editorial Guide",
    "overview": "MyBotica carousels turn one ordinary, repeated task into a compact editorial story. The system is warm and approachable rather than futuristic: generous paper-colored space, decisive dark type, physical objects, and a friendly mascot make the technology feel understandable. Each slide advances one thought, and the sequence moves from a familiar friction to a concrete interaction before asking for action.\n\nThe system is expressive through scale, contrast, and composition rather than decorative effects. Deep-green and burgundy full-bleed slides punctuate a cream reading rhythm; crisp grids and rules explain mechanisms; the canonical dragon girl appears as an active guide with a purposeful emotion. Product uncertainty is labeled in the visual hierarchy instead of being hidden in fine print.",
    "keyCharacteristics": [
      "Fixed 4:5 editorial canvases with a persistent branded header and ten-step progress rail.",
      "Cream, deep-green, and burgundy surfaces alternating to control pace and emphasis.",
      "Wide geometric Unbounded headlines paired with highly readable Golos supporting copy.",
      "Physical objects, simple diagrams, and the dragon girl used as evidence or explanation, not filler.",
      "Compact cards with modest radii, strong borders, and selective ambient shadows.",
      "One everyday scenario per carousel, expressed before the underlying technology."
    ],
    "rules": [
      {
        "name": "The Burgundy Signal Rule",
        "body": "Burgundy marks the one idea, state, or action that deserves immediate attention; it is not a decorative wash applied everywhere.",
        "section": "colors"
      },
      {
        "name": "The Three-Surface Rhythm Rule",
        "body": "Build the sequence primarily from warm cream, deep green, and burgundy full-slide fields, using white and soft green only inside those fields.",
        "section": "colors"
      },
      {
        "name": "The One Thought Per Slide Rule",
        "body": "Give every slide one dominant Unbounded statement; supporting Golos copy explains it but never competes at the same scale.",
        "section": "typography"
      },
      {
        "name": "The Tight Headline Rule",
        "body": "Unbounded headlines use tight tracking and near-solid leading; body copy never inherits that compression.",
        "section": "typography"
      },
      {
        "name": "The Fixed Editorial Frame Rule",
        "body": "Do not fluidly reflow the composition: exports target the 1080 × 1350 Instagram canvas, and each slide is art-directed within that frame.",
        "section": "layout"
      },
      {
        "name": "The Placed-On-Paper Rule",
        "body": "Use elevation to make a real or conversational object feel physically placed on the slide; data grids, lists, and structural panels remain flat.",
        "section": "elevation"
      },
      {
        "name": "The One Clipped Corner Rule",
        "body": "Conversational and character-bearing surfaces may soften three corners and clip the lower-left; structural panels use even corners or square rules.",
        "section": "shapes"
      }
    ],
    "dos": [
      "Do preserve the 1080 × 1350px frame, 76px horizontal safe area, branded header, and ten-step progress rail across the carousel.",
      "Do make one familiar life or work task the visual and narrative center before introducing AI capability.",
      "Do alternate cream, deep-green, and burgundy fields to pace the sequence and reserve burgundy for the highest-attention signal.",
      "Do use the canonical MyBotica logo and dragon girl; select her emotion to support the slide's meaning.",
      "Do label speculative mechanics, mockups, and illustrative results visibly in the hierarchy.",
      "Do use physical source objects when the story depends on a real book, tool, or other recognizable reference."
    ],
    "donts": [
      "Don't turn the carousel into a generic list of AI features, a fabricated user case, or an unqualified product promise.",
      "Don't introduce extra accent hues merely to differentiate slides; use structure, scale, and the established three-surface rhythm.",
      "Don't decorate every panel with shadows; grids, rules, and color fields are the default depth system.",
      "Don't use pills, excessive rounding, glossy gradients, or futuristic interface chrome that weakens the editorial paper character.",
      "Don't treat the dragon girl as a repeated corner sticker; she must guide, react, demonstrate, or close the story."
    ]
  }
