    body { background:#d8d3cd; display:flex; flex-direction:column; align-items:center; gap:24px; padding:24px; font-family:Golos,Arial,sans-serif; }
    .slide { position:relative; width:1080px; height:1350px; overflow:hidden; padding:68px 76px 76px; background:var(--cream); color:var(--green); display:flex; flex-direction:column; }
