    .header-note { font-size:19px; font-weight:720; letter-spacing:.03em; color:var(--muted); }
    .dark .header-note,.wine .header-note { color:rgba(255,255,255,.72); }
    h1,h2,h3 { font-family:Unbounded,sans-serif; font-weight:590; letter-spacing:-.035em; text-wrap:balance; }
    h1 { font-size:76px; line-height:1.02; }
